// RemoveOrp relationship.
// Sets o.R.Orp to nil.
// Removes o from all passed in related items' relationships struct.
func (o *Requisicao) RemoveOrp(ctx context.Context, exec boil.ContextExecutor, related *OrdemProducao) error {
	var err error

	queries.SetScanner(&o.OrpID, nil)
	if _, err = o.Update(ctx, exec, boil.Whitelist("orp_id")); err != nil {
		return errors.Wrap(err, "failed to update local table")
	}

	if o.R != nil {
		o.R.Orp = nil
	}
	if related == nil || related.R == nil {
		return nil
	}

	for i, ri := range related.R.OrpRequisicaos {
		if queries.Equal(o.OrpID, ri.OrpID) {
			continue
		}

		ln := len(related.R.OrpRequisicaos)
		if ln > 1 && i < ln-1 {
			related.R.OrpRequisicaos[i] = related.R.OrpRequisicaos[ln-1]
		}
		related.R.OrpRequisicaos = related.R.OrpRequisicaos[:ln-1]
		break
	}
	return nil
}

